text:
{
  "title_novice": "Когда ЯМР перестаёт видеть пласт",
  "summary": [
    {"text": "ЯМР неприменим в трёх условиях: при ферро- и парамагнитных минералах, при глубоких зонах кольматации и при нефтяных добавках в раствор.", "claims": ["c1", "c2", "c3"]},
    {"text": "Высокопроницаемые коллекторы с глубокой кольматацией на диаграмме ЯМР почти не выделяются.", "claims": ["c2", "c4"]}
  ],
  "claims": [
    {"key": "c1", "text": "ЯМР не применяется в разрезах с ферро- и парамагнитными минералами, особенно в вулканогенных отложениях.", "kind": "assumption", "unit_id": "u-014-7dc0b6", "page": 14, "quote": "Метод неприменим: 1) в разрезах, содержащих ферро- и парамагнитные минералы (в первую очередь в вулканогенных отложениях);", "numbers": ["1"], "question": null},
    {"key": "c2", "text": "ЯМР не применяется при наличии глубоких зон кольматации, характерных для высокопроницаемых коллекторов.", "kind": "assumption", "unit_id": "u-014-7dc0b6", "page": 14, "quote": "при наличии глубоких (более 2—3 см) зон кольматации, характерных обычно для высокопроницаемых коллекторов", "numbers": ["2—3"], "question": null},
    {"key": "c3", "text": "ЯМР не применяется, если при бурении используют нефтяные добавки в глинистый раствор.", "kind": "assumption", "unit_id": "u-014-7dc0b6", "page": 14, "quote": "при использовании нефтяных добавок в глинистый раствор", "numbers": ["3"], "question": null},
    {"key": "c4", "text": "На диаграмме ЯМР высокопроницаемые пласты с глубокой кольматацией практически не выделяются.", "kind": "observation", "unit_id": "u-014-7dc0b6", "page": 14, "quote": "последние на диаграмме ЯМР практически не выделяются", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Текст называет три условия, при которых ЯМР неприменим. Физику каждого условия автор не раскрывает.", "claims": ["c1", "c2", "c3"], "hypothesis": false},
    {"text": "ЯМР регистрирует сигнал ядер водорода в жидкости, заполняющей поры. Всё, что искажает этот сигнал у стенки скважины, мешает методу.", "claims": [], "hypothesis": true},
    {"text": "Текст указывает, что ферро- и парамагнитные минералы чаще всего встречаются в вулканогенных отложениях.", "claims": ["c1"], "hypothesis": false},
    {"text": "Почему такие минералы мешают: они меняют локальное магнитное поле в породе. Это пояснение редактора, в главе не дано.", "claims": [], "hypothesis": true},
    {"text": "Текст связывает глубокую кольматацию с высокопроницаемыми коллекторами. На диаграмме ЯМР такие коллекторы почти не выделяются.", "claims": ["c2", "c4"], "hypothesis": false},
    {"text": "Вероятная причина слепоты: сигнал приходит из слоя, где поры уже заполнены фильтратом, а не флюидом пласта. Это гипотеза редактора.", "claims": [], "hypothesis": true},
    {"text": "Текст лишь называет условие: нефтяные добавки в глинистом растворе делают ЯМР неприменимым.", "claims": ["c3"], "hypothesis": false},
    {"text": "Возможная причина: нефтяные добавки дают свой водородный сигнал, который смешивается с сигналом пластового флюида. Это гипотеза редактора.", "claims": [], "hypothesis": true}
  ],
  "practice": [
    {"text": "Перед интерпретацией ЯМР проверяют три условия: состав пород, состав раствора и признаки глубокой кольматации.", "claims": ["c1", "c2", "c3"], "hypothesis": true},
    {"text": "Если условие нарушено, слабая или пустая ЯМР-кривая не говорит об отсутствии коллектора.", "claims": ["c4"], "hypothesis": true},
    {"text": "В таком случае опираются на другие методы и данные.", "claims": [], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Автор пишет «Метод неприменим», то есть условия жёсткие. Это не снижение точности.", "claims": ["c1"], "hypothesis": false},
    {"text": "Условие о кольматации касается высокопроницаемых коллекторов, характерных для этого условия.", "claims": ["c2"], "hypothesis": false},
    {"text": "Высокопроницаемые коллекторы обычно представляют наибольший интерес. Поэтому это условие важно проверять первым.", "claims": [], "hypothesis": true},
    {"text": "Порог «2—3 см» в тексте дан как ориентир, а не как расчётная формула.", "claims": ["c2"], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Почему магнитные минералы мешают", "text": "Ферро- и парамагнетизм меняют локальное магнитное поле в породе. Это общее физическое объяснение, не из главы.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Условие 1: в разрезе есть ферро- или парамагнитные минералы, особенно в вулканогенных отложениях.", "claims": ["c1"]},
    {"text": "Условие 2: есть глубокие зоны кольматации более 2—3 см.", "claims": ["c2"]},
    {"text": "Условие 3: в глинистый раствор добавлены нефтяные добавки.", "claims": ["c3"]}
  ],
  "terms_defined": [
    {"term": "зона кольматации", "term_en": "colmatation zone", "abbr": "", "definition": "Слой у стенки скважины, где поры породы закупорены. Глубина зоны — ключевой признак. В главе термин не расшифрован; смысл дан по контексту.", "claims": ["c2"]},
    {"term": "ферро- и парамагнитные минералы", "term_en": "ferro- and paramagnetic minerals", "abbr": "", "definition": "Минералы, которые реагируют на магнитное поле: ферромагнитные — сильно, парамагнитные — слабо. Общее физическое понятие, в главе не раскрыто.", "claims": ["c1"]}
  ],
  "terms_used": ["ЯМР", "диаграмма ЯМР", "коллектор", "высокопроницаемый коллектор", "проницаемость", "разрез", "вулканогенные отложения", "глинистый раствор", "буровой раствор", "нефтяная добавка", "фильтрат бурового раствора", "сигнал свободной прецессии", "ядра водорода"],
